/// A value of the circuit: whether it is a constant decides whether a product of it is a witness.
#[derive(Clone, Copy)]
struct V {
    v: Fq,
    c: bool,
}

impl V {
    fn var(v: Fq) -> Self {
        Self { v, c: false }
    }
}

fn k(v: Fq) -> V {
    V { v, c: true }
}

fn dec(s: &str) -> Fq {
    Fq::from_str(s).expect("a field element")
}

fn add(a: V, b: V) -> V {
    V {
        v: a.v + b.v,
        c: a.c && b.c,
    }
}

fn sub(a: V, b: V) -> V {
    V {
        v: a.v - b.v,
        c: a.c && b.c,
    }
}

fn mul(a: V, b: V, w: &mut Witness<Fq>) -> V {
    if a.c || b.c {
        V {
            v: a.v * b.v,
            c: a.c && b.c,
        }
    } else {
        V::var(field::mul(a.v, b.v, w))
    }
}

/// `double x = of_int 2 * x`
fn dbl(a: V) -> V {
    V {
        v: a.v.double(),
        c: a.c,
    }
}

/// `Plonk_checks.scalars_env`'s `pow`.
fn pw(x: V, n: u64, w: &mut Witness<Fq>) -> V {
    if n == 0 {
        k(Fq::from(1u64))
    } else if n == 1 {
        x
    } else {
        let y = pw(mul(x, x, w), n / 2, w);
        if n % 2 == 0 {
            y
        } else {
            mul(x, y, w)
        }
    }
}

